"ALTER TABLE matricula.renovacao_matricula ALTER COLUMN data_cadastro TYPE timestamp USING data_cadastro::timestamp;", 
"ALTER TABLE basico.estorno_movimentacao_estudante ALTER COLUMN data_estorno TYPE timestamp USING data_estorno::timestamp;",
"DROP materialized VIEW matricula.vagas_totais_periodo;",
"ALTER TABLE matricula.renovacao_matricula ALTER COLUMN data_cancelamento TYPE timestamp USING data_cancelamento::timestamp;",
"CREATE MATERIALIZED VIEW matricula.vagas_totais_periodo TABLESPACE pg_default AS SELECT vs.id_calendario_matricula, vs.id_vaga_serie, e.id_escola, e.nome AS escola, mun.nome AS municipio, etapa.id_etapa_ensino, etapa.denominacao AS etapa, s.id_serie, s.descricao AS serie, t.id_turno, vs.periodo, t.descricao AS turno, vs.vagas_validadas, vs.vagas_ocupadas, vs.vagas_efetivadas, vagas_nee.valor::integer AS qtd_vagas_nee, vs.vagas_validadas - vs.vagas_ocupadas AS saldo_materializado, (SELECT count(r.id_renovacao_matricula) AS count FROM matricula.renovacao_matricula r WHERE r.id_vaga_serie = vs.id_vaga_serie AND r.data_cancelamento IS NULL AND r.id_nova_serie IS NULL) AS renovacao, (SELECT count(st.id_solicitacao_transferencia) AS count FROM matricula.solicitacao_transferencia st JOIN matricula.solicitacao_transferencia_processamento stp ON stp.id_solicitacao_transferencia = st.id_solicitacao_transferencia JOIN matricula.solicitacao_transferencia_opcao_escola topcao ON topcao.id_solicitacao_transferencia_opcao_escola = stp.id_opcao_escola WHERE (st.id_status = ANY (ARRAY[2, 4, 8])) AND topcao.periodo = vs.periodo AND st.id_calendario_matricula = cm.id_calendario_matricula AND topcao.id_escola = vs.id_escola AND topcao.id_serie = vs.id_serie AND topcao.id_turno = vs.id_turno AND st.id_matricula_discente_serie_gerado IS NULL AND (stp.id_status = ANY (ARRAY[2, 4, 8]))) AS transf, (SELECT count(ei.id_estudante_inscrito) AS count FROM matricula.estudante_inscrito ei JOIN matricula.estudante_inscrito_processamento eip ON eip.id_estudante_inscrito = ei.id_estudante_inscrito JOIN matricula.estudante_inscrito_opcao_escola iopcao ON iopcao.id_estudante_inscrito_opcao_escola = eip.id_opcao_escola WHERE iopcao.id_vaga_serie = vs.id_vaga_serie AND (eip.id_status = ANY (ARRAY[4, 6, 7, 1])) AND (ei.id_estudante = 0 OR ei.id_estudante IS NULL) AND (ei.id_status = ANY (ARRAY[1, 4, 6, 7]))) AS inscrito, (SELECT count(DISTINCT COALESCE(mesvc.id_matricula_estudante_serie_vaga_componente, s_1.id_matricula_discente_serie)) AS count FROM basico.matricula_estudante_serie s_1 JOIN escola.escola_etapa_ensino_serie eees ON eees.id_escola_etapa_ensino_serie = s_1.id_serie_escola LEFT JOIN basico.matricula_estudante_serie_vaga_componente mesvc ON mesvc.id_matricula_discente_serie = s_1.id_matricula_discente_serie WHERE (s_1.id_situacao_matricula_serie <> ALL (ARRAY[5, 4, 9, 6, 10, 11])) AND s_1.id_turno = vs.id_turno AND eees.id_escola = vs.id_escola AND eees.id_serie = vs.id_serie AND s_1.ano_calendario = cm.ano AND s_1.periodo = vs.periodo) AS efetivacoes, (SELECT count(DISTINCT r.id_renovacao_matricula) AS count FROM matricula.renovacao_matricula r JOIN discente d ON d.id_discente = r.id_discente JOIN comum.pessoa p ON p.id_pessoa = d.id_pessoa JOIN comum.pessoa_necessidade_especial pne ON pne.id_pessoa = p.id_pessoa WHERE r.id_vaga_serie = vs.id_vaga_serie AND r.data_cancelamento IS NULL AND r.id_nova_serie IS NULL) AS renovacao_nee, (SELECT count(DISTINCT st.id_solicitacao_transferencia) AS count FROM matricula.solicitacao_transferencia st JOIN matricula.solicitacao_transferencia_processamento stp ON stp.id_solicitacao_transferencia = st.id_solicitacao_transferencia JOIN matricula.solicitacao_transferencia_opcao_escola topcao ON topcao.id_solicitacao_transferencia_opcao_escola = stp.id_opcao_escola JOIN basico.matricula_estudante_serie mes ON mes.id_matricula_discente_serie = st.id_matricula_discente_serie JOIN discente d ON d.id_discente = mes.id_estudante JOIN comum.pessoa p ON p.id_pessoa = d.id_pessoa JOIN comum.pessoa_necessidade_especial pne ON pne.id_pessoa = p.id_pessoa WHERE (st.id_status = ANY (ARRAY[2, 4, 8])) AND topcao.periodo = vs.periodo AND st.id_calendario_matricula = cm.id_calendario_matricula AND topcao.id_escola = vs.id_escola AND topcao.id_serie = vs.id_serie AND topcao.id_turno = vs.id_turno AND st.id_matricula_discente_serie_gerado IS NULL AND (stp.id_status = ANY (ARRAY[2, 4, 8]))) AS transf_nee, (SELECT count(DISTINCT ei.id_estudante_inscrito) AS count FROM matricula.estudante_inscrito ei JOIN matricula.estudante_inscrito_processamento eip ON eip.id_estudante_inscrito = ei.id_estudante_inscrito JOIN matricula.estudante_inscrito_opcao_escola iopcao ON iopcao.id_estudante_inscrito_opcao_escola = eip.id_opcao_escola JOIN matricula.estudante_inscrito_necessidade_especial eiee ON eiee.id_estudante_inscrito = ei.id_estudante_inscrito WHERE iopcao.id_vaga_serie = vs.id_vaga_serie AND (eip.id_status = ANY (ARRAY[4, 6, 7, 1])) AND (ei.id_estudante = 0 OR ei.id_estudante IS NULL) AND (ei.id_status = ANY (ARRAY[1, 4, 6, 7]))) AS inscrito_nee, (SELECT count(DISTINCT COALESCE(mesvc.id_matricula_estudante_serie_vaga_componente, s_1.id_matricula_discente_serie)) AS count FROM basico.matricula_estudante_serie s_1 LEFT JOIN basico.matricula_estudante_serie_vaga_componente mesvc ON mesvc.id_matricula_discente_serie = s_1.id_matricula_discente_serie JOIN escola.escola_etapa_ensino_serie eees ON eees.id_escola_etapa_ensino_serie = s_1.id_serie_escola JOIN discente d ON d.id_discente = s_1.id_estudante JOIN comum.pessoa p ON p.id_pessoa = d.id_pessoa JOIN comum.pessoa_necessidade_especial pne ON pne.id_pessoa = p.id_pessoa WHERE (s_1.id_situacao_matricula_serie <> ALL (ARRAY[5, 4, 9, 6, 10, 11])) AND s_1.id_turno = vs.id_turno AND eees.id_escola = vs.id_escola AND eees.id_serie = vs.id_serie AND s_1.ano_calendario = cm.ano AND s_1.periodo = vs.periodo) AS efetivacoes_nee FROM matricula.vaga_serie vs JOIN matricula.calendario_matricula cm ON cm.id_calendario_matricula = vs.id_calendario_matricula JOIN escola.escola e ON e.id_escola = vs.id_escola JOIN comum.municipio mun ON e.id_municipio = mun.id_municipio JOIN basico.serie s ON s.id_serie = vs.id_serie JOIN basico.etapa_ensino etapa ON etapa.id_etapa_ensino = s.id_etapa_ensino JOIN ensino.turno t ON t.id_turno = vs.id_turno JOIN comum.parametro_academico vagas_nee ON vagas_nee.codigo::text = '2_2_10'::text WHERE cm.ativo AND cm.vigente AND vs.removida = false ORDER BY etapa.id_etapa_ensino, s.id_serie, t.id_turno WITH DATA;"


